/** 11-00305-BUSCA-SIGUIENTE: el movimiento solo se presenta si está vigente o eliminado y es de la consulta. */
static boolean esElegible(MovimientoDia m, ParametrosConsulta p) {
    return (m.estatus() == 1 || m.estatus() == 2)        // WKS-D01-STA
        && m.autorizacionAplicacion() == p.autorizacion() // WKS-D01-AUTAPL = WKS-PARAM-AUTAPL, 9(08)
        && m.fechaContable().equals(p.fechaContable());   // WKS-D01-FECCONT = WKS-PARAM-FECHA, 9(08) AAAAMMDD
}

// MovimientoDia.fechaContable(): LocalDate.parse("%08d".formatted(fecCont), BASIC_ISO_DATE).
// El campo es 9(08) COMP con siglo completo, no requiere pivote Y2K.

private void etiquetasServicio(MovimientoDia m, RenglonP11 r, int sistema) {
    boolean captacion = props.sistemasConNio().contains(sistema);       // 500 o 264
    r.nio(captacion ? m.nio() : "");
    r.servicio(sistema != props.sistemaCaptacion() ? "" : switch (m.envCtd()) {   // 500
        case 1  -> "SOLO CBII ";
        case 2  -> "CTD Y CBII";
        case 3  -> "SOLO CTD  ";
        default -> "";
    });
    // WKS-CVE-ENVCITI(WKS-D01-CVETRA): en Java la clave se busca, no se usa como subíndice.
    EnvioCiti env = (sistema == props.sistemaCaptacion() && m.envCtd() > 0)
            ? catalogos.busca(m.claveTransaccion()).map(ClaveTransaccion::envioCiti).orElse(EnvioCiti.NINGUNO)
            : EnvioCiti.NINGUNO;
    r.ctd(switch (env) {
        case CBII_CTD -> "CBII CTD";
        case SOLO_CTD -> "SOLO CTD";
        case NINGUNO  -> "";
    });
}

@Component
@RequiredArgsConstructor
public class DmsiiErrorTranslator {

    private final BitacoraLj bitacora;   // CALL "LJ IN LIB-DISP"

    /** 900000-CHE-STA: categoría, tipo y estructura del error, con la leyenda de WKS-TAB-ERRDMSII. */
    public long registra(String base, DataAccessException e) {
        var cat = CategoriaError.de(e);  // NOTFOUND(1) .. INTLIBERROR(21), mismo orden que la tabla
        bitacora.informativo("BASE DATOS  %s ERROR EN BD %s %02d TIPO        %s ESTRUCTURA  %s"
                .formatted(base, cat.leyenda(), cat.codigo(), cat.tipo(e), cat.estructura(e)));
        return 13;                       // MOVE 13 TO W77-MSG en las consultas
    }
}
